def encode(text):
    """Run-length encode text that holds no digits. See TASK.md."""
    if any(character in "0123456789" for character in text):
        raise ValueError("encode input must not contain digits")

    encoded = []
    index = 0
    while index < len(text):
        end = index + 1
        while end < len(text) and text[end] == text[index]:
            end += 1
        count = end - index
        if count == 1:
            encoded.append(text[index])
        else:
            encoded.append(str(count))
            encoded.append(text[index])
        index = end
    return "".join(encoded)


def decode(text):
    """Reverse `encode`. See TASK.md."""
    decoded = []
    index = 0
    while index < len(text):
        if text[index] not in "0123456789":
            decoded.append(text[index])
            index += 1
            continue

        count_start = index
        while index < len(text) and text[index] in "0123456789":
            index += 1
        count_text = text[count_start:index]
        if count_text.startswith("0") or int(count_text) <= 1 or index == len(text):
            raise ValueError("invalid run-length count")

        decoded.append(text[index] * int(count_text))
        index += 1
    return "".join(decoded)
